//! Explicit public-information rules for new fictional sessions only.
use crate::{model::*,world::World};
use serde_json::{json,Value};
pub const VERSION:&str="open-intel-v1";
pub fn validate(profile:&str)->E<()>{if profile.is_empty()||profile==VERSION{Ok(())}else{Err("未知敌情规则版本".into())}}
impl World{
 pub(crate) fn open_intel(&self)->bool{self.salvage.as_ref().map_or(self.intel_profile.as_str(),|b|b.start.intel_profile.as_str())==VERSION}
 pub(crate) fn apply_intel(&mut self,profile:&str)->E<()>{validate(profile)?;if !profile.is_empty()&&(self.campaign.is_some()||self.host_duel||!["", "night",crate::radar::RADAR_DRILL,crate::illumination::TRAINING,crate::illumination::RADAR_TRAINING,crate::challenge::VARIANT,crate::prologue::VARIANT,crate::arena::VARIANT].contains(&self.variant.as_str())&&self.salvage.is_none()){return Err("历史或权威双席模式不能启用开放敌情".into());}self.intel_profile=profile.into();if self.open_intel(){self.refresh_open_intel();}Ok(())}
 pub(crate) fn refresh_open_intel(&mut self){if !self.open_intel(){return;}for owner in 0..2{let mut previous=std::mem::take(&mut self.contacts[owner]);for s in self.ships.iter().filter(|s|s.side!=owner&&s.alive()){
  let d=&self.data.ships[s.def];let old=previous.iter().position(|c|c.ship==s.id).map(|i|previous.remove(i));let id=old.as_ref().map(|c|c.id.clone()).unwrap_or_else(||{let id=format!("C{:02}",self.next_contacts[owner]);self.next_contacts[owner]+=1;id});self.contacts[owner].push(Contact{id,x:s.p.x,y:s.p.y,heading:s.h,speed:s.speed,kind:Some(d.kind.to_lowercase()),name:Some(s.name.clone()),ship:s.id,first_cycle:old.map_or(0,|c|c.first_cycle),acquisition_base_yd:u32::MAX,acquisition_range_yd:u32::MAX});}}}
 pub(crate) fn intel_view(&self,owner:usize,view:&mut Value){if !self.open_intel(){return;}view["intel_profile"]=json!(VERSION);for(row,c)in view["contacts"].as_array_mut().unwrap().iter_mut().zip(&self.contacts[owner]){let Some(s)=self.ship(c.ship)else{continue;};let d=&self.data.ships[s.def];let creature=self.creature_intelligence(s.id);row["health"]=json!(s.hp.max(0.));row["max_health"]=json!(self.hull_max_hp(s));row["health_fraction"]=json!((s.hp/self.hull_max_hp(s)).clamp(0.,1.));row["classId"]=json!(d.id);row["characterId"]=json!(s.character);row["identified"]=json!(true);
 row["intelligence"]=creature.unwrap_or_else(||json!({"speed_max":self.max_speed(s),"attack_damage":d.gun.damage.iter().copied().fold(0.,f64::max),"attack_range":d.gun.range_yd[3]*YARD,"attack_cooldown":d.gun.reload_seconds.unwrap_or(20),"armor":d.armor_belt,"armor_deck":d.armor_deck,"weaknesses":if d.armor_belt>0.{"穿甲弹；避免舷侧交战"}else{"高爆弹；利用岛岸遮挡"}}));
 row["intelligence"]["actual_speed"]=json!(s.speed);row["intelligence"]["heading"]=json!(s.h);row["intelligence"]["hull_length"]=json!(d.length_m);row["intelligence"]["torpedoes_loaded"]=json!(s.ammo);row["intelligence"]["torpedoes_reserve"]=json!(s.torp_reserve.iter().sum::<u32>());row["intelligence"]["fire_control_damage"]=json!(s.fire_control_damage);
 row["intelligence"]["gun_barrels"]=json!(d.gun.barrels);row["intelligence"]["damage_table"]=json!(d.gun.damage);row["intelligence"]["range_table_m"]=json!(d.gun.range_yd.iter().map(|r|r*YARD).collect::<Vec<_>>());row["intelligence"]["torpedo_range"]=json!(d.torpedo.as_ref().map_or(0.,|t|t.range_yd*YARD));row["intelligence"]["fires"]=json!(s.fires.len());row["intelligence"]["flooding"]=json!(s.flooding.len());
 if row["attack"].is_null(){let ready=self.expedition_battery_ready_seconds(s);row["attack"]=json!({"kind":"naval_gun","label":"舰炮齐射","counter":"离开舷侧射界，利用岛岸","state":if ready>0{"recover"}else{"approach"},"seconds":ready,"range":d.gun.range_yd[3]*YARD,"radius":0,"shape":"circle"});}
 }}
}
#[cfg(test)]mod tests{use super::*;
 #[test]fn explicit_open_information_survives_distance_and_replay(){let mut w=World::new(42,0,"coord","","coord",0).unwrap();let old=w.observation(0);assert!(old.get("intel_profile").is_none());w.apply_intel(VERSION).unwrap();assert_eq!(w.contacts[0].len(),5);let id=w.contacts[0][0].ship;w.ship_mut(id).unwrap().p=P{x:23000.,y:13000.};w.ship_mut(id).unwrap().hp-=5.;w.update_tracks();let v=w.observation(0);assert!(v["contacts"].as_array().unwrap().iter().any(|c|c["x"].as_f64()==Some(23000.)&&c["health"].is_number()&&c["intelligence"].is_object()));let saved=w.save();assert_eq!(saved.intel_profile,VERSION);}
 #[test]fn historical_and_unknown_profiles_are_rejected(){let mut w=World::new_campaign(42,crate::campaign::live::Start::new("CAMP-ALLIES-03","story"),"coord").unwrap();assert!(w.apply_intel(VERSION).is_err());assert!(validate("unknown").is_err());}
 #[test]fn every_fictional_local_training_mode_can_opt_in(){for variant in ["","night",crate::radar::RADAR_DRILL,crate::illumination::TRAINING,crate::illumination::RADAR_TRAINING,crate::challenge::VARIANT,crate::prologue::VARIANT]{let mut w=World::new(6106,0,"coord",variant,"coord",0).unwrap();w.apply_intel(VERSION).unwrap();assert_eq!(w.contacts[0].len(),w.ships.iter().filter(|s|s.side==1&&s.alive()).count());assert_eq!(World::from_save(w.save(),w.tick).unwrap().observation(0),w.observation(0));}}
}
